1	//! Embedded Freenet node (Android-only at runtime, portable at the
2	//! type level so host `cargo test` can exercise the no-JNI fallback
3	//! paths).
4	//!
5	//! On Android, `start_embedded_node` spawns a dedicated tokio
6	//! multi-thread runtime on a background OS thread and drives the
7	//! freenet node's network-mode event loop on it. The node binds its
8	//! WebSocket client API at the default `127.0.0.1:7509`; River's
9	//! `ConnectionManager` (native impl in
10	//! `freenet_api/connection_manager.rs`) connects to that endpoint.
11	//!
12	//! The node is *separate* from the Dioxus runtime — it owns its own
13	//! tokio reactor so the UI's event loop isn't sharing scheduling
14	//! pressure with wasmtime contract execution, and so that long-lived
15	//! node tasks (peer connection recv loops, transport drivers) don't
16	//! have to be `'static` against the Dioxus scope.
17	//!
18	//! **Network mode, not Local.** A Local-mode node only serves what's
19	//! been PUT to its own stores — Android users could create their own
20	//! rooms but could not join any room shared via invitation link,
21	//! because the network state never reaches their device. Network
22	//! mode makes the device a real Freenet peer that fetches contracts
23	//! and states through peers and gateways. See
24	//! `openspec/changes/android-bundled-node/design.md` decision #2 for
25	//! the full rationale and the mobile-NAT risks.
26	//!
27	//! Remaining caveats (tracked in the OpenSpec change's tasks.md):
28	//! - No foreground service yet — Android may kill the process when
29	//!   the app backgrounds (tasks 5.x).
30	//!
31	//! On non-Android targets, `start_embedded_node` is a no-op stub so
32	//! the module compiles for host `cargo check` / `cargo test` without
33	//! pulling in freenet, tokio, jni, or ndk-context.
34	
35	use std::path::PathBuf;
36	
37	/// Hardcoded fallback for the embedded Freenet node's storage dir.
38	///
39	/// Matches the package id in `ui/Dioxus.toml` (`org.freenet.river`).
40	/// On a real device the runtime path comes from
41	/// `Context.getFilesDir()` via JNI ([`android_files_dir`]) — this
42	/// constant is only used when the JNI lookup fails (emulator without
43	/// an attached Activity, unusual launch path, etc.) so the node can
44	/// still boot rather than aborting.
45	pub(crate) const FREENET_DATA_DIR_FALLBACK: &str =
46	    "/data/data/org.freenet.river/files/freenet";
47	
48	/// Resolve the app's private files dir at runtime via JNI.
49	///
50	/// Walks the standard Android startup handles:
51	/// 1. `ndk_context::android_context()` exposes the `JavaVM` + the
52	///    activity's `Context` jobject, published by ndk-glue / wry / tao
53	///    during native startup.
54	/// 2. Attach the current thread to the VM.
55	/// 3. Call `Context.getFilesDir() -> java/io/File`.
56	/// 4. Call `File.getAbsolutePath() -> java/lang/String`.
57	/// 5. Decode the Java string to a Rust `String` and join `"freenet"`
58	///    onto it, giving the node its own subdirectory under the app's
59	///    private files area.
60	///
61	/// Returns `None` on any JNI failure (ndk-context not populated, VM
62	/// attach failure, `NoSuchMethodError`) AND on every non-Android
63	/// target. Callers fall back to [`FREENET_DATA_DIR_FALLBACK`] and
64	/// emit a `warn!` so the failure is visible in logcat.
65	#[cfg(target_os = "android")]
66	pub(crate) fn android_files_dir() -> Option<PathBuf> {
67	    use jni::objects::{JObject, JString};
68	    use jni::JavaVM;
69	
70	    let ctx = ndk_context::android_context();
71	    let vm = unsafe { JavaVM::from_raw(ctx.vm().cast()) }.ok()?;
72	    let activity = unsafe { JObject::from_raw(ctx.context().cast()) };
73	
74	    let mut env = vm.attach_current_thread().ok()?;
75	
76	    // Context.getFilesDir() -> java/io/File
77	    let files_dir = env
78	        .call_method(&activity, "getFilesDir", "()Ljava/io/File;", &[])
79	        .ok()?
80	        .l()
81	        .ok()?;
82	
83	    // File.getAbsolutePath() -> java/lang/String
84	    let path_jstr = env
85	        .call_method(&files_dir, "getAbsolutePath", "()Ljava/lang/String;", &[])
86	        .ok()?
87	        .l()
88	        .ok()?;
89	
90	    let path_jstr: JString = path_jstr.into();
91	    let rust_path: String = env.get_string(&path_jstr).ok()?.into();
92	
93	    Some(PathBuf::from(rust_path).join("freenet"))
94	}
