286	    /// `ui/android/kotlin/dev/dioxus/main/RiverNodeService.kt`).
287	    ///
288	    /// Fires the parked oneshot so the freenet-worker tokio runtime
289	    /// drops the network node + transport drivers in an orderly fashion
290	    /// rather than being SIGKILL'd by Android. Best-effort: if the node
291	    /// hasn't reached `run_network_node` yet (e.g. user mashed Stop
292	    /// during boot), the sender is `None` and we no-op.
293	    ///
294	    /// JNI ABI: the function name must match the fully-qualified
295	    /// Java/Kotlin class + method name, with `.` replaced by `_`. Any
296	    /// rename on either side must be made in lock-step.
297	    ///
298	    /// Signature uses the raw `jni::sys` C types so we don't carry a
299	    /// `JNIEnv<'local>` lifetime through a `#[no_mangle] extern "system"`
300	    /// — we never call back into the JVM from this function, so the
301	    /// raw pointers are all we need.
302	    #[no_mangle]
303	    pub unsafe extern "system" fn Java_dev_dioxus_main_RiverNodeService_nativeOnServiceStop(
304	        _env: *mut jni::sys::JNIEnv,
305	        _class: jni::sys::jclass,
306	    ) {
307	        match SHUTDOWN_TX.lock() {
308	            Ok(mut slot) => match slot.take() {
309	                Some(tx) => {
310	                    if tx.send(()).is_err() {
311	                        warn!("Embedded node already gone — shutdown signal dropped");
312	                    } else {
313	                        info!("Shutdown signal sent to embedded node");
314	                    }
315	                }
316	                None => {
317	                    info!(
318	                        "RiverNodeService.onDestroy fired before embedded node reached \
319	                         the event loop — nothing to signal"
320	                    );
321	                }
322	            },
323	            Err(e) => {
324	                error!("SHUTDOWN_TX mutex poisoned: {e}");
325	            }
326	        }
327	    }
328	
329	    /// Stage the bundled fallback `gateways.toml` + PEMs into
330	    /// `config_dir` and `secrets_dir`, ONLY if
331	    /// `config_dir/gateways.toml` doesn't already exist.
332	    ///
333	    /// Freenet's [`NodeConfig::new`] tries the live remote fetch
334	    /// first; on success, it overwrites `config_dir/gateways.toml`
335	    /// (and the PEMs in `secrets_dir`) with the freshly-fetched
336	    /// copy. On failure, it falls back to parsing whatever is
337	    /// already at `config_dir/gateways.toml`. By pre-staging the
338	    /// bundled fallback when that file is absent, we guarantee an
339	    /// offline first-launch still has a valid gateways list to
340	    /// parse — without it the node would error out with `Cannot
341	    /// initialize node without gateways`.
342	    ///
343	    /// We do NOT overwrite an existing `gateways.toml`: any file
344	    /// already at that path is freenet's own cache from a prior
345	    /// successful fetch and is at least as fresh as our bundle.
346	    ///
347	    /// The bundled PEMs match the snapshot in `ui/assets/freenet/`.
348	    /// If the live fetch later succeeds, freenet overwrites the
349	    /// same PEM filenames in `secrets_dir` with the fresh content —
350	    /// our stale bytes don't linger.
351	    fn stage_fallback_gateways(config_dir: &Path, secrets_dir: &Path) -> std::io::Result<()> {
352	        let gateways_file = config_dir.join("gateways.toml");
353	        if gateways_file.exists() {
354	            return Ok(());
355	        }
356	        std::fs::create_dir_all(config_dir)?;
357	        std::fs::create_dir_all(secrets_dir)?;
358	
359	        let nova_path = secrets_dir.join("public.nova.gw.pem");
360	        let vega_path = secrets_dir.join("public.vega.gw.pem");
361	        std::fs::write(&nova_path, FALLBACK_NOVA_PUBKEY)?;
362	        std::fs::write(&vega_path, FALLBACK_VEGA_PUBKEY)?;
363	
364	        // Build the TOML with absolute paths. Freenet's local-cache
365	        // parser deserializes `public_key` straight into a `PathBuf`
366	        // and opens the file with no further path resolution;
367	        // relative paths would be resolved against the CWD, which
368	        // is undefined on Android.
369	        let toml = format!(
370	            "# Bundled fallback (used because freenet's live fetch failed).\n\
371	             [[gateways]]\n\
372	             public_key = \"{}\"\n\
373	             [gateways.address]\n\
374	             hostname = \"nova.locut.us:31337\"\n\
375	             \n\
376	             [[gateways]]\n\
377	             public_key = \"{}\"\n\
378	             [gateways.address]\n\
379	             hostname = \"vega.locut.us:31337\"\n",
380	            nova_path.display(),
381	            vega_path.display(),
382	        );
383	        std::fs::write(&gateways_file, toml)?;
384	
385	        info!(
386	            "Staged fallback gateways.toml + 2 PEMs at {:?} ({} bytes bundled)",
387	            gateways_file,
388	            FALLBACK_GATEWAYS_TOML.len(),
389	        );
390	        Ok(())
391	    }
392	}
