261	mod imp {
262	    use crate::components::app::freenet_api::error::SynchronizerError;
263	    use crate::components::app::freenet_api::freenet_synchronizer;
264	    use crate::components::app::freenet_api::freenet_synchronizer::SynchronizerStatus;
265	    use crate::components::app::{SYNC_STATUS, WEB_API};
266	    use crate::freenet_transport::WebApi as RiverWebApi;
267	    use crate::platform::spawn_local;
268	    use dioxus::logger::tracing::{error, info, warn};
269	    use dioxus::prelude::ReadableExt;
270	    use freenet_stdlib::client_api::WebApi as StdlibWebApi;
271	    use futures::channel::mpsc::UnboundedSender;
272	    use tokio::sync::mpsc;
273	
274	    /// Connect to a Freenet node over native tokio-tungstenite.
275	    ///
276	    /// Mirrors the wasm `imp::ConnectionManager` surface so the caller in
277	    /// `freenet_synchronizer` doesn't need to know which transport is
278	    /// active. Two structural differences from the browser path:
279	    ///
280	    /// * `freenet-stdlib`'s native `WebApi` is poll-based
281	    ///   (`recv().await -> HostResult`) rather than callback-based, and
282	    ///   both `send` and `recv` take `&mut self` — a single value can't
283	    ///   be shared. We spawn one *owner task* that holds the stdlib
284	    ///   `WebApi`, `select!`s between an inbound-request channel and
285	    ///   `recv()`, and feeds responses into the existing
286	    ///   `SynchronizerMessage::ApiResponse` channel. The rest of the
287	    ///   synchronizer interacts with the node through a thin
288	    ///   `crate::freenet_transport::WebApi` wrapper (a sender handle on
289	    ///   the request channel) stored in `WEB_API` — same call shape as
290	    ///   the browser impl.
291	    /// * No auth-token handshake: a locally-bundled node binds
292	    ///   `127.0.0.1` and accepts loopback connections without one. The
293	    ///   `__FREENET_AUTH_TOKEN__` window-global injection only exists
294	    ///   in the gateway-hosted web build.
295	    pub struct ConnectionManager {
296	        connected: bool,
297	    }
298	
299	    impl ConnectionManager {
300	        pub fn new() -> Self {
301	            info!("Creating new native ConnectionManager (tokio-tungstenite)");
302	            Self { connected: false }
303	        }
304	
305	        pub fn is_connected(&self) -> bool {
306	            *SYNC_STATUS.read() == SynchronizerStatus::Connected
307	        }
308	
309	        pub async fn initialize_connection(
310	            &mut self,
311	            message_tx: UnboundedSender<freenet_synchronizer::SynchronizerMessage>,
312	        ) -> Result<(), SynchronizerError> {
313	            let websocket_url = node_url();
314	            info!("Connecting to Freenet node at: {}", websocket_url);
315	            *SYNC_STATUS.write() = SynchronizerStatus::Connecting;
316	            self.connected = false;
317	
318	            let (stream, _resp) = tokio_tungstenite::connect_async(&websocket_url)
319	                .await
320	                .map_err(|e| {
321	                    let error_msg = format!("Failed to connect WebSocket: {}", e);
322	                    error!("{}", error_msg);
323	                    SynchronizerError::WebSocketError(error_msg)
324	                })?;
325	
326	            // stdlib's native WebApi (from `regular.rs`) — spawns its
327	            // own internal reader/writer pair around the tokio-tungstenite
328	            // stream and exposes `send` + `recv` over channels.
329	            let mut stdlib_api = StdlibWebApi::start(stream);
330	
331	            // Channel that the rest of the app pushes `ClientRequest`s
332	            // into; the owner task below drains it and calls
333	            // `stdlib_api.send`. Bounded at 32 mirrors stdlib's own
334	            // internal queueing — bigger numbers buy nothing if the
335	            // node is the bottleneck and only mask backpressure.
336	            let (req_tx, mut req_rx) = mpsc::channel::<freenet_stdlib::client_api::ClientRequest<'static>>(32);
337	
338	            let response_tx = message_tx.clone();
339	            spawn_local(async move {
340	                loop {
341	                    tokio::select! {
342	                        // Outbound: app → node
343	                        next_req = req_rx.recv() => {
344	                            let Some(req) = next_req else {
345	                                // All `WebApi` handles dropped; shut down.
346	                                break;
347	                            };
348	                            if let Err(e) = stdlib_api.send(req).await {
349	                                warn!("Failed to forward request to node: {}", e);
350	                                // Treat send failure as connection loss
351	                                // so the synchronizer reconnects rather
352	                                // than silently dropping requests.
353	                                break;
354	                            }
355	                        }
356	                        // Inbound: node → app
357	                        host_result = stdlib_api.recv() => {
358	                            let mapped = host_result.map_err(|e| {
359	                                SynchronizerError::WebSocketError(e.to_string())
360	                            });
361	                            if response_tx
362	                                .unbounded_send(
363	                                    freenet_synchronizer::SynchronizerMessage::ApiResponse(mapped),
364	                                )
365	                                .is_err()
366	                            {
367	                                // Synchronizer message channel closed.
368	                                break;
369	                            }
370	                        }
371	                    }
372	                }
373	                info!("Native WebApi owner task exited; signalling ConnectionLost");
374	                let _ = response_tx.unbounded_send(
375	                    freenet_synchronizer::SynchronizerMessage::ConnectionLost,
376	                );
377	            });
378	
379	            // Publish a handle the rest of the synchronizer can use
380	            // exactly as it uses stdlib's wasm `WebApi`.
381	            *WEB_API.write() = Some(RiverWebApi::new(req_tx));
382	            *SYNC_STATUS.write() = SynchronizerStatus::Connected;
383	            self.connected = true;
384	            info!("Native WebSocket connection established");
385	            Ok(())
386	        }
387	    }
388	
389	    /// Where to connect for the local/embedded Freenet node.
390	    ///
391	    /// On Android (and any other native build for now) we point at the
392	    /// loopback WebSocket the bundled node binds. The port mirrors
393	    /// `freenet local`'s default. Desktop builds will likely want
394	    /// `RIVER_NODE_URL` as a config knob — that's intentionally not
395	    /// wired yet.
396	    fn node_url() -> String {
397	        // freenet's default ws_api port (see `WebsocketApiArgs::ws_api_port`
398	        // in `freenet/src/config.rs` — defaults to 7509 in local mode).
399	        "ws://127.0.0.1:7509/v1/contract/command?encodingProtocol=native".to_string()
400	    }
401	}
