2386	async fn test_attested_contract_passed_to_delegate(ctx: &mut TestContext) -> TestResult {
2387	    use freenet::dev_tool::AuthToken;
2388	    use tokio_tungstenite::tungstenite::client::IntoClientRequest;
2389	
2390	    const TEST_DELEGATE: &str = "test-delegate-attested";
2391	
2392	    #[derive(Debug, Serialize, Deserialize)]
2393	    enum InboundAppMessage {
2394	        CheckAttested,
2395	    }
2396	
2397	    #[derive(Debug, Deserialize)]
2398	    enum OutboundAppMessage {
2399	        Attested(Option<Vec<u8>>),
2400	    }
2401	
2402	    let gateway = ctx.node("gateway")?;
2403	
2404	    // Step 1: pre-register a token → contract-id in the node's attested_contracts map.
2405	    // This simulates a client that authenticated via an HTTP contract page before opening
2406	    // a WebSocket connection.
2407	    let token = AuthToken::from("test-attested-contract-token-e2e-12345".to_string());
2408	    let expected_contract_id = ContractInstanceId::new([42u8; 32]);
2409	    gateway.insert_origin_contract(token.clone(), expected_contract_id);
2410	
2411	    // Step 2: compile / load the delegate WASM
2412	    let params = Parameters::from(vec![]);
2413	    let delegate = load_delegate(TEST_DELEGATE, params.clone())?;
2414	    let delegate_key = delegate.key().clone();
2415	
2416	    // Step 3: connect via WebSocket carrying the Bearer token.
2417	    // The WebSocket proxy will look up the token in the shared attested_contracts map
2418	    // and attach the resolved ContractInstanceId to every subsequent request.
2419	    let ws_url = gateway.ws_url();
2420	    let mut ws_request = ws_url.as_str().into_client_request()?;
2421	    ws_request.headers_mut().insert(
2422	        "Authorization",
2423	        format!("Bearer {}", token.as_str()).parse()?,
2424	    );
2425	    let (stream, _) = connect_async(ws_request).await?;
2426	    let mut client = WebApi::start(stream);
2427	
2428	    // Step 4: register the delegate
2429	    client
2430	        .send(ClientRequest::DelegateOp(
2431	            freenet_stdlib::client_api::DelegateRequest::RegisterDelegate {
2432	                delegate: delegate.clone(),
2433	                cipher: TEST_DELEGATE_CIPHER,
2434	                nonce: TEST_DELEGATE_NONCE,
2435	            },
2436	        ))
2437	        .await?;
2438	
2439	    let resp = timeout(Duration::from_secs(10), client.recv()).await??;
2440	    match resp {
2441	        HostResponse::DelegateResponse { key, .. } => {
2442	            assert_eq!(key, delegate_key, "Delegate key mismatch on register");
2443	            tracing::info!("Delegate registered: {key}");
2444	        }
2445	        other @ HostResponse::ContractResponse(_)
2446	        | other @ HostResponse::QueryResponse(_)
2447	        | other @ HostResponse::Ok
2448	        | other => bail!("Expected DelegateResponse on register, got {:?}", other),
2449	    }
2450	
2451	    // Step 5: send an ApplicationMessage that causes the delegate to echo back
2452	    // whatever bytes it received in the `attested` parameter.
2453	    let _app_id = ContractInstanceId::new([0; 32]);
2454	    let payload = bincode::serialize(&InboundAppMessage::CheckAttested)?;
2455	    let app_msg = ApplicationMessage::new(payload);
2456	
2457	    client
